        existing += 1;
        if (metadata.size === 0) {
          zero += 1;
        } else if (metadata.size >= 5) {
          const fd = await open(absolute, 'r');
          try {
            const { buffer } = await fd.read(Buffer.alloc(5), 0, 5, 0);
            head = buffer.toString('ascii');
          } finally {
            await fd.close();
          }
        }
        if (head !== '%PDF-') corrupt += 1;
      } catch (err) {
        corrupt += 1;
      }
